import { useMutation } from "@tanstack/react-query";
import { FileDown } from "lucide-react";

import { FieldError } from "@/components/feedback/error-message";
import { Button } from "@/components/ui/button";
import { downloadFile } from "@/lib/api/download";

/** Downloads an authenticated PDF (report or invoice) generated by the backend. */
function DownloadButton({ url, filename, children = "Download PDF", ...buttonProps }) {
  const download = useMutation({ mutationFn: () => downloadFile(url, filename) });
  return (
    <span className="inline-flex flex-col gap-1">
      <Button
        variant="outline"
        size="sm"
        isLoading={download.isPending}
        onClick={() => download.mutate()}
        {...buttonProps}
      >
        <FileDown aria-hidden="true" />
        {children}
      </Button>
      {download.error ? <FieldError>{download.error.message}</FieldError> : null}
    </span>
  );
}

export { DownloadButton };
